
# KcELECTRA fine-tuning for "From Reviews to Reliable Actions" (same split as baseline.py)
import os, json, time, zlib, base64, random
import numpy as np, pandas as pd, torch
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score, f1_score
from transformers import AutoTokenizer, AutoModelForSequenceClassification
MODEL_NAME, TRAIN_SIZE, EPOCHS, MAX_LEN, BATCH, LR, SEED = "beomi/KcELECTRA-base-v2022", 100_000, 1, 64, 64, 5e-5, 42
random.seed(SEED); np.random.seed(SEED); torch.manual_seed(SEED)
device = "cuda" if torch.cuda.is_available() else "cpu"
print("DEVICE", device, torch.cuda.get_device_name(0) if device == "cuda" else "")
if not os.path.exists("naver_shopping.txt"):
    os.system("wget -q -O naver_shopping.txt https://raw.githubusercontent.com/bab2min/corpus/master/sentiment/naver_shopping.txt")
df = pd.read_csv("naver_shopping.txt", sep="\t", header=None, names=["rating", "text"], quoting=3)
df["text"] = df["text"].astype(str).str.strip()
df = df[df["text"].str.len() > 0].drop_duplicates(subset="text").reset_index(drop=True)
df["label"] = (df["rating"] >= 4).astype(int); df["review_id"] = np.arange(len(df))
train, test = train_test_split(df, test_size=0.2, stratify=df["label"], random_state=SEED)
SAMPLE_IDS = [int(x) for x in zlib.decompress(base64.b64decode("")).decode().split(",")]
train = train[~train["review_id"].isin(SAMPLE_IDS)]
if TRAIN_SIZE and len(train) > TRAIN_SIZE: train = train.sample(TRAIN_SIZE, random_state=SEED)
print("TRAIN", len(train), "TEST", len(test))
tok = AutoTokenizer.from_pretrained(MODEL_NAME)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_NAME, num_labels=2).to(device)
def batches(texts, labels=None, shuffle=False):
    idx = np.arange(len(texts))
    if shuffle: np.random.shuffle(idx)
    for i in range(0, len(idx), BATCH):
        j = idx[i:i + BATCH]
        enc = tok([texts[k] for k in j], padding=True, truncation=True, max_length=MAX_LEN, return_tensors="pt")
        enc = {k: v.to(device) for k, v in enc.items()}
        yield enc, (torch.tensor([labels[k] for k in j], device=device) if labels is not None else None)
tr_x, tr_y = train["text"].tolist(), train["label"].tolist()
steps = EPOCHS * ((len(tr_x) + BATCH - 1) // BATCH)
opt = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=0.01)
sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=LR, total_steps=steps, pct_start=0.06, anneal_strategy="linear")
amp = device == "cuda"; scaler = torch.amp.GradScaler("cuda", enabled=amp)
model.train(); step = 0; t0 = time.time()
for ep in range(EPOCHS):
    for enc, y in batches(tr_x, tr_y, shuffle=True):
        with torch.autocast(device_type="cuda", dtype=torch.float16, enabled=amp):
            loss = torch.nn.functional.cross_entropy(model(**enc).logits, y)
        opt.zero_grad(); scaler.scale(loss).backward(); scaler.step(opt); scaler.update(); sched.step(); step += 1
        if step % 200 == 0 or step == steps: print(f"STEP {step}/{steps} loss {loss.item():.4f} {time.time()-t0:.0f}s", flush=True)
@torch.no_grad()
def p_pos(texts):
    model.eval(); out = []
    for enc, _ in batches(texts):
        with torch.autocast(device_type="cuda", dtype=torch.float16, enabled=amp):
            out.append(torch.softmax(model(**enc).logits.float(), -1)[:, 1].cpu().numpy())
    return np.concatenate(out)
pt = p_pos(test["text"].tolist()); pred = (pt >= 0.5).astype(int)
metrics = {"model": MODEL_NAME, "train_size": len(train), "epochs": EPOCHS, "train_seconds": round(time.time()-t0),
           "accuracy": round(accuracy_score(test["label"], pred), 4), "macro_f1": round(f1_score(test["label"], pred, average="macro"), 4)}
print("METRICS " + json.dumps(metrics))
by_id = df.set_index("review_id")["text"]
ps = p_pos([by_id[i] for i in SAMPLE_IDS])
packed = base64.b64encode(zlib.compress(np.round(ps * 10000).astype(np.uint16).tobytes(), 9)).decode()
print("SCORES_BEGIN" + packed + "SCORES_END")
